import os
import base64
import cPickle

class AuthFail(Exception):
    pass

def extract_secure_data(headers):
    try:
        auth_token = headers.get('AuthToken', None)
        if auth_token is None:
            raise AuthFail
        
        decoded_data = base64.b64decode(auth_token)
        unpickled_data = cPickle.loads(decoded_data)
        
        secure_data = unpickled_data.get('secure_data', None)
        if secure_data is None:
            raise AuthFail
        
        return secure_data
    except:
        raise AuthFail

